<?php if(!$orders): ?><div class="empty"><h3>Todavía no hay pedidos.</h3><p>Los nuevos pedidos van a aparecer acá.</p></div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Cliente</th><th>Total</th><th>Pago</th><th>Fabricación</th><th></th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td>#<?= $o['id'] ?><small><?= date('d/m/Y',strtotime($o['created_at'])) ?></small></td><td><?= e($o['customer_name']) ?><small><?= e($o['email']) ?></small></td><td><?= money($o['total_cents']) ?></td><td><?= e(paymentLabel($o['payment_status'])) ?></td><td><span class="badge"><?= e($o['status']) ?></span></td><td><a class="text-link" href="/admin/pedidos/<?= $o['id'] ?>">Ver ↗</a></td></tr><?php endforeach ?></tbody></table></div><?php endif ?>
